/// <summary>
/// Additional form events for UnitOfMeasureConversion
/// </summary>
internal final class METUnitOfMeasureConversion_FormEvents
{

    
}

Method.Source:
    /// <summary>
    /// UnitOfMeasureConversion_OnInitialized
    /// </summary>
    /// <param name="sender">sender</param>
    /// <param name="e">e</param>
    [FormEventHandler(formStr(UnitOfMeasureConversion), FormEventType::Initialized)]
    public static void UnitOfMeasureConversion_OnInitialized(xFormRun sender, FormEventArgs e)
    {
        FormRun fr = sender;

        void disableEdit(FormDataSource ds)
        {
            ds.allowCreate(false);
            ds.allowEdit(false);
            ds.allowDelete(false);
        }

        if(fr.args().menuItemName() == menuItemDisplayStr(METUnitOfMeasureConversionView))
        {
            fr.design().controlName(formControlStr(UnitOfMeasureConversion, AddButton)).enabled(false);
            fr.design().controlName(formControlStr(UnitOfMeasureConversion, EditButton)).enabled(false);
            fr.design().controlName(formControlStr(UnitOfMeasureConversion, DeleteButtonStandard)).enabled(false);

            fr.design().controlName(formControlStr(UnitOfMeasureConversion, AddButtonIntraClass)).enabled(false);
            fr.design().controlName(formControlStr(UnitOfMeasureConversion, EditButtonIntraClass)).enabled(false);
            fr.design().controlName(formControlStr(UnitOfMeasureConversion, DeleteButtonIntraClass)).enabled(false);

            fr.design().controlName(formControlStr(UnitOfMeasureConversion, AddButtonInterClass)).enabled(false);
            fr.design().controlName(formControlStr(UnitOfMeasureConversion, EditButtonInterClass)).enabled(false);
            fr.design().controlName(formControlStr(UnitOfMeasureConversion, DeleteButtonInterClass)).enabled(false);
        }
    }
